#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.Vanilla.Localization;
using MVZ2Logic;
using MVZ2Logic.Commands;
using MVZ2Logic.Definitions;
using MVZ2Logic.Localization;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Level;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Commands
{
    [AutoCommandDefinition(VanillaCommandNames.cheat)]
    public class Cheat : CommandDefinition
    {
        public Cheat(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Invoke(string[] parameters)
        {
            var level = Global.Level.GetLevel();
            if (level == null)
                return;
            var cheatCode = parameters[0];
            if (cheatCode == "all")
            {
                CheatAll(level);
            }
            else
            {
                CheatSingle(level, cheatCode);
            }
        }
        private void CheatAll(LevelEngine level)
        {
            var game = Global.Game;

            using var disabledBuffsItem = ListPool<string>.Rent();
            var disabledBuffs = disabledBuffsItem.Value;
            foreach (var pair in cheatBuffs)
            {
                var buffId = pair.Value.cheatBuffID;
                if (!level.HasBuff(buffId))
                {
                    disabledBuffs.Add(pair.Key);
                }
            }
            if (disabledBuffs.Count > 0)
            {
                foreach (var disabled in disabledBuffs)
                {
                    if (!cheatBuffs.TryGetValue(disabled, out var info))
                    {
                        throw new ArgumentException(Global.Localization.GetTextParticular(VanillaStrings.COMMAND_CHEAT_NOT_FOUND, LogicStrings.CONTEXT_COMMAND_OUTPUT, disabled));
                    }
                    BuffDefinition? buffDefinition = game.GetBuffDefinition(info.cheatBuffID);
                    string cheatNameKey = info.message;
                    if (buffDefinition != null)
                    {
                        level.AddBuff(info.cheatBuffID);
                        var msg = VanillaStrings.COMMAND_CHEAT_ENABLED;
                        var cheatName = Global.Localization.GetTextParticular(cheatNameKey, VanillaStrings.CONTEXT_COMMAND_CHEAT_NAME);
                        PrintLine(Global.Localization.GetTextParticular(msg, LogicStrings.CONTEXT_COMMAND_OUTPUT, cheatName));
                    }
                }
            }
            else
            {
                foreach (var pair in cheatBuffs)
                {
                    var buffId = pair.Value.cheatBuffID;
                    var cheatNameKey = pair.Value.message;
                    level.RemoveBuffs(buffId);
                    var msg = VanillaStrings.COMMAND_CHEAT_DISABLED;
                    var cheatName = Global.Localization.GetTextParticular(cheatNameKey, VanillaStrings.CONTEXT_COMMAND_CHEAT_NAME);
                    PrintLine(Global.Localization.GetTextParticular(msg, LogicStrings.CONTEXT_COMMAND_OUTPUT, cheatName));
                }
            }
        }
        private void CheatSingle(LevelEngine level, string cheatCode)
        {
            var game = Global.Game;

            if (!cheatBuffs.TryGetValue(cheatCode, out var info))
            {
                throw new ArgumentException(Global.Localization.GetTextParticular(VanillaStrings.COMMAND_CHEAT_NOT_FOUND, LogicStrings.CONTEXT_COMMAND_OUTPUT, cheatCode));
            }
            BuffDefinition? buffDefinition = game.GetBuffDefinition(info.cheatBuffID);
            string cheatNameKey = info.message;
            if (buffDefinition != null)
            {
                string msg;
                if (level.HasBuff(buffDefinition))
                {
                    level.RemoveBuffs(buffDefinition);
                    msg = VanillaStrings.COMMAND_CHEAT_DISABLED;
                }
                else
                {
                    level.AddBuff(buffDefinition);
                    msg = VanillaStrings.COMMAND_CHEAT_ENABLED;
                }
                var cheatName = Global.Localization.GetTextParticular(cheatNameKey, VanillaStrings.CONTEXT_COMMAND_CHEAT_NAME);
                PrintLine(Global.Localization.GetTextParticular(msg, LogicStrings.CONTEXT_COMMAND_OUTPUT, cheatName));
            }
        }
        public static readonly Dictionary<string, (NamespaceID cheatBuffID, string message)> cheatBuffs = new Dictionary<string, (NamespaceID cheatBuffID, string message)>()
        {
            { "godmode", (VanillaBuffID.Level.debugGodmode, VanillaStrings.CHEAT_NAME_GODMODE) },
            { "energy", (VanillaBuffID.Level.debugEnergy, VanillaStrings.CHEAT_NAME_ENERGY) },
            { "recharge", (VanillaBuffID.Level.debugNoRecharge, VanillaStrings.CHEAT_NAME_RECHARGE) },
            { "starshard", (VanillaBuffID.Level.debugStarshard, VanillaStrings.CHEAT_NAME_STARSHARD) },
        };
    }
}